static inline uint32_t ss_ref_dot4_s8(uint32_t rs1, uint32_t rs2) {
	int32_t acc = 0;
	for (int i = 0; i < 4; i++)
		acc += (int32_t)(int8_t)(rs1 >> (8 * i)) * (int32_t)(int8_t)(rs2 >> (8 * i));
	return (uint32_t)acc;
}

static inline uint32_t ss_ref_dot2_s8(uint32_t rs1, uint32_t rs2) {
	int32_t acc = 0;
	for (int i = 0; i < 2; i++)
		acc += (int32_t)(int8_t)(rs1 >> (8 * i)) * (int32_t)(int8_t)(rs2 >> (8 * i));
	return (uint32_t)acc;
}

static inline uint32_t ss_ref_mul2_s8(uint32_t rs1, uint32_t rs2) {
	int16_t p0 = (int16_t)((int8_t)rs1 * (int8_t)rs2);
	int16_t p1 = (int16_t)((int8_t)(rs1 >> 8) * (int8_t)(rs2 >> 8));
	return ((uint32_t)(uint16_t)p1 << 16) | (uint16_t)p0;
}

static inline uint32_t ss_ref_dot4p_s8(uint32_t rs1, uint32_t rs2) {
	int32_t acc = 0;
	for (int i = 0; i < 4; i++)
		acc += (int32_t)(int8_t)(rs1 >> (8 * i)) * (int32_t)(int8_t)(rs2 >> (8 * i));
	return (uint32_t)acc;
}

static inline uint32_t ss_ref_dot4_u8s8(uint32_t rs1, uint32_t rs2) {
	int32_t acc = 0;
	for (int i = 0; i < 4; i++)
		acc += (int32_t)(uint8_t)(rs1 >> (8 * i)) * (int32_t)(int8_t)(rs2 >> (8 * i));
	return (uint32_t)acc;
