static inline uint32_t ss_ref_dacc_s8(uint32_t rs1, uint32_t rs2) {
	/* stateful: acc += dot4(rs1, rs2); funct3=1 reads and clears (see ss_dacc_s8_rd) */
	static int32_t acc;
	for (int i = 0; i < 4; i++)
		acc += (int32_t)(int8_t)(rs1 >> (8 * i)) * (int32_t)(int8_t)(rs2 >> (8 * i));
	return (uint32_t)acc;
}

static inline uint32_t ss_ref_sum4_s8(uint32_t rs1, uint32_t rs2) {
	(void)rs2;
	int32_t acc = 0;
	for (int i = 0; i < 4; i++)
		acc += (int32_t)(int8_t)(rs1 >> (8 * i));
	return (uint32_t)acc;
}

static inline uint32_t ss_ref_dot2_s16(uint32_t rs1, uint32_t rs2) {
	int32_t acc = (int32_t)(int16_t)rs1 * (int16_t)rs2;
	acc += (int32_t)(int16_t)(rs1 >> 16) * (int16_t)(rs2 >> 16);
	return (uint32_t)acc;
