// first attempt: the read path forgets to clear (funct3 compare uses the stale bit)
module ss_insn_dacc_s8 (
	input  wire        clk,
	input  wire        resetn,
	input  wire        valid,
	input  wire [2:0]  funct3,
	input  wire [31:0] rs1,
	input  wire [31:0] rs2,
	output wire [31:0] rd
);
	wire signed [15:0] p0 = $signed(rs1[ 7: 0]) * $signed(rs2[ 7: 0]);
	wire signed [15:0] p1 = $signed(rs1[15: 8]) * $signed(rs2[15: 8]);
	wire signed [15:0] p2 = $signed(rs1[23:16]) * $signed(rs2[23:16]);
	wire signed [15:0] p3 = $signed(rs1[31:24]) * $signed(rs2[31:24]);
	wire signed [18:0] dot = (p0 + p1) + (p2 + p3);
	reg  signed [31:0] acc;
	wire signed [31:0] acc_next = acc + dot;
	always @(posedge clk) begin
		if (!resetn)
			acc <= 0;
		else if (valid)
			acc <= acc_next;
	end
	assign rd = (funct3 == 3'd1) ? {{0{acc[31]}}, acc} : {{0{acc_next[31]}}, acc_next};
endmodule

