// 25-bit accumulator: 512 x 16384 = 2^23 needs 25 signed bits
module ss_insn_daccn_s8 (
	input  wire        clk,
	input  wire        resetn,
	input  wire        valid,
	input  wire [2:0]  funct3,
	input  wire [31:0] rs1,
	input  wire [31:0] rs2,
	output wire [31:0] rd
);
