	wire signed [15:0] p1 = $signed(rs1[15: 8]) * $signed(rs2[15: 8]);
	wire signed [15:0] p2 = $signed(rs1[23:16]) * $signed(rs2[23:16]);
	wire signed [15:0] p3 = $signed(rs1[31:24]) * $signed(rs2[31:24]);
